using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.Additive.BenfieldLippard;

internal sealed class StabilizationDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Arith/Additive/BenfieldLippard/Stabilization.";
    private static readonly LibraryNoteRef Paper =
        LibraryNoteRef.Create("D5/L/Semigroups/benfieldlippard2025positivepowers");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The positive exceptional offsets stabilize at the gaps of a monoid generated by shifted powers.",
        H("Stabilization of exceptional offsets"),
        Blocks(
            Describe.Lean(
                DescribeId.Create("exception-offsets"),
                DeclarationHandle.Create(Prefix + "exceptions"),
                H("Positive exceptions at length j"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Paper),
                Blocks(Paragraph(Text(
                    "These are the positive s for which j+s has no representation by exactly j positive kth powers."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("shifted-power-generators"),
                DeclarationHandle.Create(Prefix + "generators"),
                H("Shifted powers"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Paper),
                Blocks(Paragraph(Text(
                    "The generators at exponent k are the numbers a^k−1 for positive natural bases a."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("generated-offsets"),
                DeclarationHandle.Create(Prefix + "offsets"),
                H("The offset monoid"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Paper),
                Blocks(Paragraph(Text(
                    "The offset monoid is the additive closure of the shifted powers."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("offset-gaps"),
                DeclarationHandle.Create(Prefix + "gaps"),
                H("The gaps of the offset monoid"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Paper),
                Blocks(Paragraph(Text(
                    "The gaps are the positive naturals outside the offset monoid."))),
                DescribeRole.Definition),
            Describe.Lean(
                DescribeId.Create("generator-membership"),
                DeclarationHandle.Create(Prefix + "generator_mem"),
                H("Every shifted power is an offset"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Paper),
                Blocks(Paragraph(Text(
                    "If a is positive, its shifted kth power belongs to the monoid generated by all such powers."))),
                DescribeRole.Lemma),
            Describe.Lean(
                DescribeId.Create("shifted-power-representation"),
                DeclarationHandle.Create(Prefix + "offset_iff_exists_posRep"),
                H("Offsets and exact-length representations"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Paper),
                Blocks(
                    Paragraph(Text(
                        "Subtract one from every positive kth power in a representation of j+s. "
                        + "The summands now add to the offset s and each is a generator a^k−1. "
                        + "Conversely, any finite sum of generators gives a positive power representation by adding one per summand."))
                ),
                DescribeRole.Theorem),
            Describe.Lean(
                DescribeId.Create("finite-stabilization"),
                DeclarationHandle.Create(Prefix + "stabilization"),
                H("The common finite exception set"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Paper),
                Blocks(
                    Paragraph(Text(
                        "Padding a representation with ones preserves its offset. "
                        + "The fixed-length positive Waring result gives a reference length j₀ ≥ 1 with finitely many exceptions. "
                        + "For each exception at j₀ that belongs to the offset monoid, choose a witness length at which it has a representation. "
                        + "Set J to the maximum of j₀ and the supremum of these witness lengths, with empty supremum zero. "
                        + "For j ≥ J, pad each of the chosen witnesses with ones to length j. "
                        + "The bound j ≥ j₀ lets us also pad the representations already available at j₀. "
                        + "Thus at every j ≥ J the positive exceptions are precisely the gaps of the monoid.")),
                    Paragraph(Text(
                        "The reference length matters even if no exceptions disappear from it. "
                        + "For squares, choose j₀ in the stable range. The witness supremum is then zero, "
                        + "yet 6 is an exceptional offset at length 1 because 7 is not a square. "
                        + "The offset 6 belongs to the monoid by the length-2 representation 8 = 2² + 2².")),
                    Paragraph(Text(
                        "Benfield and Lippard's Theorem 1.1 credits Zenkin [65] with eventual fixed-length cofiniteness. "
                        + "For every k ≥ 2 and each fixed j ≥ G(1,k), all but finitely many positive integers have a representation of length j. "
                        + "Their Conjecture 1.2 gives the stable finite offset formulation, which the padding argument above derives from the formal fixed-length Waring bridge."))
                ),
                DescribeRole.Theorem)
        )));
}
